      `    <DT><A HREF="${encodeEntities(row.url)}" ADD_DATE="${addDate}" LAST_MODIFIED="${lastMod}"${tagsAttr}>${encodeEntities(row.title)}</A>`
    );
  }
  lines.push('</DL><p>');
  return lines.join('\n') + '\n';
}

